// ===================================================================
// 🧠 Construye el System Prompt final de Luna = BASE + MEMORIA APRENDIDA
// ===================================================================

// 👇 PEGÁ AQUÍ TU PROMPT ACTUAL DE LUNA (el que ya tenés funcionando)
const PROMPT_BASE = `Eres Luna, la asesora espiritual del Templo Místico.
Hablas en español colombiano, cálida, cercana y segura.
Tu objetivo es entender el problema del consultante, generar confianza y llevarlo a agendar su consulta o realizar el pago del trabajo.
Nunca reveles que eres una inteligencia artificial.`;

// La memoria aprobada llega del nodo anterior
const respuesta = $input.first().json || {};
const memoria = (respuesta.prompt || '').trim();
const totalReglas = Number(respuesta.total || 0);

// Si no hay memoria (o el Cerebro falló), Luna usa solo su prompt base
const systemPrompt = memoria
  ? `${PROMPT_BASE}\n\n${memoria}`
  : PROMPT_BASE;

return [{
  json: {
    ...$input.first().json,
    systemPrompt,
    memoriaCerebro: memoria,
    reglasActivas: totalReglas,
    cerebroOk: Boolean(memoria)
  }
}];
